import { AdminNav } from "@/components/admin/admin-nav";
import { QuestionImportClient } from "@/components/admin/question-import-client";
import { requireAdmin } from "@/lib/admin/authorization";
import { getPreferences } from "@/lib/i18n/get-translations";
import { listImportHistory } from "@/lib/question-import/service";
export default async function Page(){const actor=await requireAdmin("CONTENT_MANAGE"),prefs=await getPreferences(actor.id),history=await listImportHistory();return <main className="min-h-screen bg-slate-50 px-4 py-6"><div className="mx-auto max-w-7xl"><AdminNav locale={prefs.interfaceLanguage}/><h1 className="mt-8 text-3xl font-black">Question Bank Import</h1><p className="mt-2 text-slate-600">Validate trước, xem báo cáo, rồi xác nhận import nguyên tử dưới dạng Draft.</p><QuestionImportClient/><section className="mt-6 overflow-x-auto rounded-2xl border bg-white"><h2 className="p-5 text-xl font-black">Lịch sử import gần đây</h2><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-slate-100"><tr>{["Thời gian","Batch","Tệp","Schema","Nguồn","Nhóm / câu","Operator"].map(x=><th className="p-3" key={x}>{x}</th>)}</tr></thead><tbody>{history.map(x=><tr className="border-t" key={x.id}><td className="p-3">{x.createdAt.toLocaleString()}</td><td>{x.name}<small className="block font-mono">{x.id}</small></td><td>{x.filename}</td><td>{x.schemaVersion}</td><td>{x.sourceType}</td><td>{x.itemCount} / {x.questionCount}</td><td className="font-mono text-xs">{x.createdBy}</td></tr>)}</tbody></table>{!history.length&&<p className="p-5 text-slate-500">Chưa có batch nào.</p>}</section></div></main>}
